import{_ as t,o,c as a,a5 as r}from"./chunks/framework.CXroN2RO.js";const k=JSON.parse('{"title":"パケットが欠けたときのTCPとQUICの配送を比べる","description":"","frontmatter":{"title":"パケットが欠けたときのTCPとQUICの配送を比べる","study":{"source":"新規執筆","section":"practice","format":"sample","status":"published","domain":"network","collection":"stream-loss-observation","order":1,"summary":"パケットが一つ欠ける場面を動かし、受信済みのデータをアプリへ渡せる範囲がTCPとQUICでどう違うかを確認する。","aliases":["TCP","QUIC","HTTP/2","HTTP/3","HOL blocking","head-of-line blocking","ストリーム","パケット欠落"],"verification":"IETFのTCP・QUIC・HTTP/3仕様と照合。ブラウザーで教材の操作を確認（2026-11-07）"}},"headers":[],"relativePath":"practice/network/stream-loss-observation.md","filePath":"practice/network/stream-loss-observation.md"}'),s={name:"practice/network/stream-loss-observation.md"};function d(c,e,i,l,n,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="パケットが欠けたときのtcpとquicの配送を比べる" tabindex="-1">パケットが欠けたときのTCPとQUICの配送を比べる <a class="header-anchor" href="#パケットが欠けたときのtcpとquicの配送を比べる" aria-label="Permalink to &quot;パケットが欠けたときのTCPとQUICの配送を比べる&quot;">​</a></h1><p>アプリがA・Bという二つのデータ列を扱うとします。HTTP/2のように一つのTCP接続に両方を載せる場合、TCPは一つの順序付きバイト列として配送します。HTTP/3のように別々のQUICストリームへ分ける場合、QUICはストリームごとに順序を保ちます。同じデータが同じ順で到着すると仮定し、欠けたデータの後ろがどこまで待つかを比べます。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-2.2" target="_blank" rel="noreferrer">RFC 9293 §2.2</a> · <a href="https://www.rfc-editor.org/rfc/rfc9114.html#section-1.1" target="_blank" rel="noreferrer">RFC 9114 §1.1–1.2</a></p><h2 id="ブラウザーで試す" tabindex="-1">ブラウザーで試す <a class="header-anchor" href="#ブラウザーで試す" aria-label="Permalink to &quot;ブラウザーで試す&quot;">​</a></h2><p><a href="/study/samples/network/stream-loss-observation/index.html">比較図を開く</a></p><ol><li>最初は<code>A0</code>を運ぶパケットが欠落し、<code>B0</code>・<code>A1</code>・<code>B1</code>が受信側に届いた場面を表示します。TCPでは三つとも待機し、QUICでは<code>B0</code>と<code>B1</code>が配送済みになります。<code>A1</code>は同じストリームの<code>A0</code>を待ちます。</li><li><strong>1段進める</strong>を押して、欠けていた<code>A0</code>のデータが届いたときに、待っていたデータが配送されることを確認します。</li><li><strong>最初に戻す</strong>を押し、失うパケットを<code>B0</code>に変えて4段目まで進めます。TCPでは最初の<code>A0</code>まで、QUICでは<code>A0</code>と<code>A1</code>が配送されます。</li><li>欠落を<strong>なし</strong>に変えると、4段目でどちらも全データを配送できます。</li></ol><table tabindex="0"><thead><tr><th>4段目までに欠けたデータ</th><th>TCPでアプリへ渡せるデータ</th><th>QUICでアプリへ渡せるデータ</th></tr></thead><tbody><tr><td><code>A0</code></td><td>なし</td><td><code>B0</code>・<code>B1</code></td></tr><tr><td><code>B0</code></td><td><code>A0</code></td><td><code>A0</code>・<code>A1</code></td></tr><tr><td><code>A1</code></td><td><code>A0</code>・<code>B0</code></td><td><code>A0</code>・<code>B0</code>・<code>B1</code></td></tr><tr><td><code>B1</code></td><td><code>A0</code>・<code>B0</code>・<code>A1</code></td><td><code>A0</code>・<code>B0</code>・<code>A1</code></td></tr></tbody></table><h2 id="教材の範囲" tabindex="-1">教材の範囲 <a class="header-anchor" href="#教材の範囲" aria-label="Permalink to &quot;教材の範囲&quot;">​</a></h2><p>「配送」は、トランスポートが順序をそろえ、アプリが読み取れるようにする段階です。実際のQUICパケットには複数のストリームのデータが載ることがあり、そのパケットを失うと複数のストリームに欠落が生じます。また、輻輳制御やアプリ側の依存関係は別のストリームにも影響し得ます。教材では送信・到着の予定を固定し、順序待ちだけを図にしています。段数は経過時間や再送の待ち時間を表しません。<a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-2.2" target="_blank" rel="noreferrer">RFC 9000 §2.2</a> · <a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-13.3" target="_blank" rel="noreferrer">RFC 9000 §13.3</a> · <a href="https://www.rfc-editor.org/rfc/rfc9114.html#section-4.2.1" target="_blank" rel="noreferrer">RFC 9114 §4.2.1</a></p><h2 id="run-locally" tabindex="-1">手元で動かす <a class="header-anchor" href="#run-locally" aria-label="Permalink to &quot;手元で動かす {#run-locally}&quot;">​</a></h2><p><a href="/study/samples/network/stream-loss-observation/index.html" download>index.html</a>、<a href="/study/samples/network/stream-loss-observation/main.js" download>main.js</a>、<a href="/study/samples/network/stream-loss-observation/styles.css" download>styles.css</a>を同じフォルダーに保存します。Pythonが入っていれば、そのフォルダーで次を実行し、ブラウザーで<code>http://127.0.0.1:8000/</code>を開きます。サーバーは <code>Ctrl+C</code> で止められます。</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m http.server </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bind </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span></span></code></pre></div><p><code>main.js</code>の<code>snapshot</code>が各段の到着と配送を計算します。TCPは送信順で最初の欠落まで、QUICは同じストリームの自分までのデータがすべて到着した部分を取り出します。教材内の操作はブラウザーで完結します。</p><h2 id="関連記事" tabindex="-1">関連記事 <a class="header-anchor" href="#関連記事" aria-label="Permalink to &quot;関連記事&quot;">​</a></h2><ul><li><a href="/study/network/quic-and-http3.html">QUICとHTTP/3</a></li><li><a href="/study/network/tcp-sockets.html">TCPソケットとバイトストリーム</a></li><li><a href="/study/network/udp-datagrams.html">UDPとデータグラム</a></li></ul>',14)])])}const m=t(s,[["render",d]]);export{k as __pageData,m as default};
